  "SK"::varchar(2048) AS sk,
  COALESCE(value->'type'->>'S', value->'type'->>'N')::varchar(64) AS type,
  COALESCE(value->'src'->>'S', value->'src'->>'N')::varchar(8) AS src,
  COALESCE(value->'updated_at'->>'S', value->'updated_at'->>'N')::varchar(32) AS updated_at,
  NULLIF(COALESCE(value->'product_id'->>'N', value->'product_id'->>'S'), '')::integer AS product_id,
  COALESCE(value->'name'->>'S', value->'name'->>'N')::varchar(65535) AS name,
  COALESCE(value->'product_number'->>'S', value->'product_number'->>'N')::varchar(65535) AS product_number,
  NULLIF(COALESCE(value->'safety_stock_level'->>'N', value->'safety_stock_level'->>'S'), '')::integer AS safety_stock_level,
  NULLIF(COALESCE(value->'reorder_point'->>'N', value->'reorder_point'->>'S'), '')::integer AS reorder_point,
  NULLIF(COALESCE(value->'stock_qty'->>'N', value->'stock_qty'->>'S'), '')::integer AS stock_qty
FROM landing."aw-inventory"
WHERE COALESCE(value->'type'->>'S', value->'type'->>'N')::varchar(64) = 'InventoryProduct' AND COALESCE((value->'deleted'->>'BOOL')::boolean, false) = false;

-- aw-inventory/InventoryTransaction  <- Production.TransactionHistory, Production.TransactionHistoryArchive
CREATE MATERIALIZED VIEW stg.inventory_transaction AS
SELECT
  "PK"::varchar(2048) AS pk,
  "SK"::varchar(2048) AS sk,
  COALESCE(value->'type'->>'S', value->'type'->>'N')::varchar(64) AS type,
  COALESCE(value->'src'->>'S', value->'src'->>'N')::varchar(8) AS src,
  COALESCE(value->'updated_at'->>'S', value->'updated_at'->>'N')::varchar(32) AS updated_at,
  NULLIF(COALESCE(value->'transaction_id'->>'N', value->'transaction_id'->>'S'), '')::integer AS transaction_id,
  NULLIF(COALESCE(value->'product_id'->>'N', value->'product_id'->>'S'), '')::integer AS product_id,
  NULLIF(COALESCE(value->'reference_order_id'->>'N', value->'reference_order_id'->>'S'), '')::integer AS reference_order_id,
  NULLIF(COALESCE(value->'reference_order_line_id'->>'N', value->'reference_order_line_id'->>'S'), '')::integer AS reference_order_line_id,
  NULLIF(COALESCE(value->'transaction_date'->>'S', value->'transaction_date'->>'N'), '')::timestamp AS transaction_date,
  COALESCE(value->'transaction_type'->>'S', value->'transaction_type'->>'N')::varchar(65535) AS transaction_type,
  NULLIF(COALESCE(value->'quantity'->>'N', value->'quantity'->>'S'), '')::integer AS quantity,
  NULLIF(COALESCE(value->'actual_cost'->>'N', value->'actual_cost'->>'S'), '')::decimal(19,4) AS actual_cost,
  NULLIF(COALESCE(value->'modified_date'->>'S', value->'modified_date'->>'N'), '')::timestamp AS modified_date,
  (value->'archived'->>'BOOL')::boolean AS archived
FROM landing."aw-inventory"
WHERE COALESCE(value->'type'->>'S', value->'type'->>'N')::varchar(64) = 'InventoryTransaction' AND COALESCE((value->'deleted'->>'BOOL')::boolean, false) = false;

